// Tool de Vapi: el lead no puede confirmar la reunión y pide reagendar.
// Camila NO mueve la cita: Clinera todavía no expone un endpoint para eso.
// Lo que hace es dejar constancia de la preferencia y avisar a Google Chat
// para que una persona tome el caso y vuelva a llamar.
const body = $input.first().json.body || {};
const msg = body.message || {};
const tc = (msg.toolCallList || msg.toolCalls || [])[0] || {};
let args = (tc.function && tc.function.arguments) || {};
if (typeof args === 'string') { try { args = JSON.parse(args); } catch (e) { args = {}; } }

const meta = (msg.call && msg.call.metadata) || msg.metadata || {};
const vars = (msg.call && msg.call.assistantOverrides && msg.call.assistantOverrides.variableValues) || {};
const limpiar = (v) => String(v == null ? '' : v).replace(/[\r\n\t]+/g, ' ').trim();

const datos = {
  toolCallId: tc.id || '',
  nombre: limpiar(args.nombre || vars.nombre),
  clinica: limpiar(args.clinica || vars.nombre_clinica),
  telefono: limpiar(args.telefono || vars.lead_phone || (msg.call && msg.call.customer && msg.call.customer.number)),
  email: limpiar(args.email || vars.email_lead),
  demoActual: limpiar(args.fecha_demo_actual || vars.fecha_demo || meta.fecha_demo),
  // Lo que el lead dijo textualmente: "la próxima semana en la mañana",
  // "el jueves después de las cuatro". No se interpreta acá: va tal cual,
  // para que quien devuelva la llamada sepa qué ofrecerle.
  preferencia: limpiar(args.preferencia_reagenda || args.preferencia),
  motivo: limpiar(args.motivo || 'No pudo confirmar la reunión agendada'),
  filaBaserow: limpiar(args.baserow_row_id || args.monday_item_id || meta.mondayItemId),
};

const linea = (etiqueta, valor) => (valor ? '*' + etiqueta + ':* ' + valor + '\n' : '');
datos.textoChat =
  '🔄 *Reagendar demo — el lead no pudo confirmar*\n\n' +
  linea('Nombre', datos.nombre) +
  linea('Clínica', datos.clinica) +
  linea('Teléfono', datos.telefono) +
  linea('Email', datos.email) +
  linea('Demo agendada', datos.demoActual) +
  linea('Cuándo le acomoda', datos.preferencia || '(no lo dijo — preguntar al llamar)') +
  linea('Motivo', datos.motivo) +
  '\n_Lo pidió durante la llamada de confirmación de Camila (IA). Hay que llamarlo, acordar la hora y moverla a mano en Clinera._' +
  (datos.filaBaserow ? '\n\nVer en Baserow: https://core.oacg.cl/database/41/table/152/row/' + datos.filaBaserow : '');

return [{ json: datos }];

// Lo que Camila recibe de vuelta. Es una instrucción para ella, no algo que
// deba leer literal: cierra con la frase acordada y sin prometer una hora,
// porque la hora la confirma una persona después.
const d = $('Extraer Solicitud').first().json;
const aviso = $input.first().json || {};
const llego = !(aviso && aviso.error);

const resultado = llego
  ? 'SOLICITUD DE REAGENDA REGISTRADA. El equipo ya fue notificado y va a llamar para cerrar la nueva hora. '
    + 'Cierra la llamada con: "Perfecto, dejame confirmar bien el horario y le escribo de vuelta, esta bien?". '
    + 'NO prometas una fecha ni una hora concreta, no ofrezcas horarios y no insistas. Despidete cordialmente.'
  : 'NO SE PUDO REGISTRAR LA SOLICITUD. Igual cierra con: "Perfecto, dejame confirmar bien el horario y le escribo de vuelta, esta bien?" '
    + 'y despidete cordialmente. El equipo lo revisa igual.';

return [{ json: { results: [{ toolCallId: d.toolCallId, result: resultado }] } }];
